import{_ as t,o as n,c as o,aa as r}from"./chunks/framework.oWfRcsIL.js";const u=JSON.parse(`{"title":"Burp Suite extension","description":"Load a finding's reproduction chain into Burp Repeater with the syslifters.ai Burp extension.","frontmatter":{"title":"Burp Suite extension","description":"Load a finding's reproduction chain into Burp Repeater with the syslifters.ai Burp extension."},"headers":[],"relativePath":"integrations/burp-extension.md","filePath":"integrations/burp-extension.md"}`),a={name:"integrations/burp-extension.md"};function s(i,e,d,p,l,h){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="burp-suite-extension" tabindex="-1">Burp Suite extension <a class="header-anchor" href="#burp-suite-extension" aria-label="Permalink to &quot;Burp Suite extension&quot;">​</a></h1><p>The Burp Suite extension loads a confirmed finding into Burp so you can reproduce and extend it by hand.</p><p>For each finding you send, it:</p><ul><li>opens one <strong>Repeater</strong> tab per request, in the order the requests were sent, named <code>DAST#&lt;finding&gt; &lt;n&gt;/&lt;N&gt; &lt;step&gt;</code> (for example <code>DAST#42 1/3 login</code>);</li><li>adds every request with its captured response to <strong>Organizer</strong>, with the agent&#39;s note for that step attached;</li><li>shows the whole chain (step, method, URL, status, note) in the extension&#39;s own <strong>DAST</strong> tab.</li></ul><h2 id="download-and-install" tabindex="-1">Download and install <a class="header-anchor" href="#download-and-install" aria-label="Permalink to &quot;Download and install&quot;">​</a></h2><p><a href="/downloads/dast-burp.jar" download>Download dast-burp.jar</a> (current version 0.1.0)</p><p>Requirements: Burp Suite Professional or Community (2025.x or newer) and Java 17 or newer.</p><ol><li>In Burp, open <strong>Extensions</strong> → <strong>Installed</strong> → <strong>Add</strong>.</li><li>Set <strong>Extension type</strong> to <strong>Java</strong> and select <code>dast-burp.jar</code>.</li><li>A new <strong>DAST</strong> tab appears in Burp&#39;s top bar.</li></ol><h2 id="pair-burp-with-a-project" tabindex="-1">Pair Burp with a project <a class="header-anchor" href="#pair-burp-with-a-project" aria-label="Permalink to &quot;Pair Burp with a project&quot;">​</a></h2><p>A pairing code connects one Burp instance to one project.</p><ol><li>In syslifters.ai, open the project and go to the <strong>Findings</strong> tab.</li><li>Click <strong>Generate code</strong>. The code appears in the <strong>Burp pairing code</strong> field.</li><li>In Burp&#39;s <strong>DAST</strong> tab, fill in: <ul><li><strong>DAST URL</strong>: the address you open syslifters.ai at.</li><li><strong>Label</strong> (optional): a name for this Burp instance, shown next to &quot;Burp connected&quot; in syslifters.ai.</li><li><strong>Pairing code</strong>: paste the code, or click <strong>Paste</strong> to take it from the clipboard.</li></ul></li><li>Click <strong>Connect</strong>. The status changes to connected, and the Findings tab shows <strong>Burp connected</strong>.</li></ol><p>Burp connects out to syslifters.ai. It opens no listener, so nothing is exposed on your machine. Burp remembers the URL, label and code and reconnects automatically after a dropped connection or a restart.</p><div class="tip custom-block"><p class="custom-block-title">Each code belongs to one project</p><p>A code only works for the project it was generated in. Generate a new code when you switch projects, and paste it into Burp.</p></div><h2 id="send-a-finding-to-burp" tabindex="-1">Send a finding to Burp <a class="header-anchor" href="#send-a-finding-to-burp" aria-label="Permalink to &quot;Send a finding to Burp&quot;">​</a></h2><p>Click <strong>Burp</strong> next to a finding on the <strong>Findings</strong> tab. The button is only enabled once a pairing code is set. When Burp has loaded the requests, syslifters.ai shows how many Repeater tabs were created.</p><p>What Burp receives depends on how the finding was verified:</p><ul><li><strong>Curated chain.</strong> The verifier replays every finding cleanly and marks each step. Burp receives only the requests of that replay, grouped into named steps with the agent&#39;s notes.</li><li><strong>Unfiltered capture.</strong> If a finding has no marked replay, Burp receives the captured traffic to the affected hosts instead, capped at 50 requests. Click <strong>Re-test</strong> on the finding to get a curated chain.</li></ul><h2 id="repeater-tab-groups" tabindex="-1">Repeater tab groups <a class="header-anchor" href="#repeater-tab-groups" aria-label="Permalink to &quot;Repeater tab groups&quot;">​</a></h2><p>Burp&#39;s extension API cannot create Repeater tab groups or put tabs into one. To keep the <code>DAST#…</code> tabs together, set <strong>Settings</strong> → <strong>Tools</strong> → <strong>Repeater</strong> → <strong>Default group for new tabs</strong> once. The shared <code>DAST#</code> prefix also keeps them next to each other.</p><h2 id="without-the-extension" tabindex="-1">Without the extension <a class="header-anchor" href="#without-the-extension" aria-label="Permalink to &quot;Without the extension&quot;">​</a></h2><p>You can download the same reproduction chain as JSON, with each request and response base64-encoded:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/findings/&lt;finding-id&gt;/burp-bundle/?download=1</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause and fix</th></tr></thead><tbody><tr><td>Status shows <code>Closed (4404 …)</code></td><td>The code is unknown, for example because it was mistyped or the project was deleted. Generate a new code.</td></tr><tr><td>Connection fails with HTTP 403</td><td>The <strong>DAST URL</strong> does not match the address syslifters.ai is served at. Use exactly the URL you open in the browser.</td></tr><tr><td>Findings tab shows <strong>Burp not connected</strong></td><td>Burp is not running, the extension is unloaded, or Burp uses a different code. Check the status in Burp&#39;s <strong>DAST</strong> tab.</td></tr><tr><td>The <strong>Burp</strong> button is disabled</td><td>No pairing code is set on the Findings tab, or the page lost its connection. Generate a code or reload the page.</td></tr><tr><td>Burp shows <code>UNFILTERED</code></td><td>The finding has no marked replay. Re-test the finding.</td></tr></tbody></table>',24)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
